import { STORAGE_KEY, copy, initialState, preset, saveVersion, restoreVersion, exportPlan } from './model.js';
const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
let state = initialState();
let storageAvailable = true;
try { const saved = JSON.parse(localStorage.getItem(STORAGE_KEY)); if (saved?.team && Array.isArray(saved.versions) && saved.insight) state = saved; } catch { storageAvailable = false; }
let page = location.hash.slice(1) || 'home';
let mode = 'full'; let busy = false; let stage = 0; let job = 0; let role = 'head'; let mobileOpen = false;
let libraryQuery = ''; let libraryType = 'all';
const nav = [['home','教练工作台','home'],['teams','球队与周期','team'],['design','训练设计','spark'],['library','方案库','book'],['feedback','训练反馈','note'],['organization','机构协作','people']];
const iconPaths = { home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3M20 2v4M18 4h4',book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4V4M13 7a3 3 0 0 1 3-3h5v15h-5a4 4 0 0 0-3 2',note:'M8 3H5v18h14V3h-3M9 2h6v4H9V2M8 11h8M8 15h6',people:'M7 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 10a3 3 0 1 0 0-6M1 21v-3a6 6 0 0 1 12 0v3M16 14a5 5 0 0 1 7 4v3',arrow:'M4 12h16M14 6l6 6-6 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',menu:'M4 6h16M4 12h16M4 18h16',calendar:'M4 5h16v16H4V5M8 2v6M16 2v6M4 10h16',ball:'m12 7 5 4-2 6H9l-2-6 5-4M12 2v5M2 9l5 2M5 20l4-3M19 20l-4-3M22 9l-5 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name] || iconPaths.note}"/></svg>`;
const btn = (text, action, style = 'primary', extra = '') => `<button class="${style}" data-action="${action}" ${/\btype=/.test(extra)?'':'type="button"'} ${extra}>${text}</button>`;
function persist() { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); storageAvailable = true; } catch { storageAvailable = false; toast('本浏览器无法保存；请导出所需方案。'); } updateSaved(); }
function updateSaved() { const node = $('.saved'); if (node) node.textContent = storageAvailable ? '已保存本浏览器' : '当前仅保留在页面中'; }
let toastTimer;
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('visible'), 3500); }
function pitch() { return `<svg class="pitch" viewBox="0 0 580 235" role="img" aria-label="虚构训练场示意：两片4对4方向比赛场地，非精确尺寸图"><rect x="22" y="22" width="536" height="190" rx="2" fill="none" stroke="#c4d5bc" stroke-width="1.4"/><path d="M290 22v190M22 72h49v90H22M558 72h-49v90h49" stroke="#c4d5bc" fill="none"/><circle cx="290" cy="117" r="31" fill="none" stroke="#c4d5bc"/><path d="m148 137 45-43m-9 0h9v9m177 36 49-44m-9 0h9v9" fill="none" stroke="#e6d69b" stroke-width="2" stroke-dasharray="5 4"/>${[[115,70],[151,144],[224,73],[220,167],[350,70],[386,145],[459,73],[453,170]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="7" fill="#e1eab8"/>`).join('')}${[[112,169],[180,93],[245,132],[69,104],[347,171],[415,95],[480,132],[305,99]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="7" fill="#dbb076"/>`).join('')}<text x="145" y="226" fill="#e2e9d7" font-size="10">4 v 4 · A 场</text><text x="381" y="226" fill="#e2e9d7" font-size="10">4 v 4 · B 场</text></svg>`; }
function heroArt() { return `<svg viewBox="0 0 220 175" aria-hidden="true"><g transform="translate(18 9) rotate(-9 90 75)"><rect x="9" y="18" width="170" height="120" rx="4" fill="#afc296"/><rect x="21" y="30" width="146" height="96" fill="none" stroke="#e6eddb" stroke-width="1.5"/><path d="M94 30v96M21 56h25v44H21M167 56h-25v44h25" fill="none" stroke="#e6eddb"/><circle cx="94" cy="78" r="19" fill="none" stroke="#e6eddb"/><path d="m58 98 38-33 36 22" stroke="#f8faf3" fill="none" stroke-width="2" stroke-dasharray="5 4"/><circle cx="58" cy="98" r="5" fill="#355a42"/><circle cx="96" cy="65" r="5" fill="#355a42"/><circle cx="132" cy="87" r="5" fill="#355a42"/></g><circle cx="178" cy="135" r="25" fill="#f3f5e8" stroke="#b2c29c"/><path d="m178 122 10 8-4 12h-12l-4-12 10-8M178 110v12M154 127l14 3M163 156l9-14M195 155l-11-13M202 127l-14 3" stroke="#9caf87" fill="none" stroke-width="1.5"/></svg>`; }
function header(title, subtitle, action = '') { return `<div class="page-header"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`; }
function card(title, body, action = '') { return `<section class="card"><div class="card-head"><h2>${title}</h2>${action}</div><div class="card-body">${body}</div></section>`; }
function home() {
  const events = [{day:'25',month:'周日',title:state.current?.title || '向前传递，接应与创造空间',time:'16:00–17:00',status:state.eventStatus},{day:'24',month:'周六',title:'控球后寻找向前线路',time:'17:00–18:00',status:'planned'},{day:'21',month:'周三',title:'观察、移动与小组配合',time:'17:00–18:00',status:'completed'}];
  return header('把每一堂训练，连成成长。','2026年10月25日，星期日 · 青禾青训',btn(`${icon('spark')} 开始备课`,'go-design')) + `<section class="hero"><div><span class="eyebrow">THIS WEEK · 训练重点</span><h2>让接应成为习惯，<br>让向前多一种选择。</h2><p>${esc(state.team.name)} · ${esc(state.cycle.name)}<br>本周期目标：${esc(state.cycle.goal)}</p><div class="actions">${btn('从本周目标开始 '+icon('arrow'),'go-design')}${btn('查看球队与周期','go-teams','quiet')}</div></div><div class="hero-art">${heroArt()}</div></section><div class="stats">${[[events.length,'本周训练安排','场','calendar','虚构演示周安排'],[state.current?1:0,'当前训练方案','份','book','生成后自动保存'],[events.filter(e=>e.status==='completed').length,'已完成训练','场','check','记录执行状态'],[state.feedback.length,'已记录现场反馈','条','note','观察证据，保留依据']].map(([v,l,u,i,t])=>`<section class="stat"><div class="stat-label">${l}${icon(i)}</div><div class="stat-value">${v}<span>${u}</span></div><small>${t}</small></section>`).join('')}</div><div class="two-col"><div><section class="card"><div class="card-head"><h2>本周训练日程</h2><span class="count">10.19 — 10.25 · 演示周</span></div><div class="week-strip">${['一','二','三','四','五','六','日'].map((d,i)=>`<div class="day ${i===6?'current':''}"><span>周${d}</span><strong>${19+i}</strong><span class="day-dot ${![2,6].includes(i)?'empty':''}"></span></div>`).join('')}</div>${events.map((e,i)=>`<div class="session-row"><div class="timebox"><strong>${e.day}</strong>${e.month}</div><div class="session-info"><h3>${e.title}</h3><p>${e.time} · U12 蓝队 · ${i===0?esc(state.cycle.venue):'训练场'}</p></div><div class="row-end"><span class="pill ${e.status==='completed'?'gray':e.status==='cancelled'?'gray':'amber'}">${{planned:'计划中',completed:'已完成',cancelled:'已取消'}[e.status]}</span>${btn(i===2?'反馈工作台':'查看安排',i===2?'go-feedback':i===0?'event':'schedule','text-link',`data-event="${i}"`)}</div></div>`).join('')}</section>${card('球队的长期方向',`<p style="font-size:13px;margin:0">${esc(state.team.goal)}</p><p class="aside-tip">阶段目标来自当前周期，临时安排不会改写长期档案。</p>`,btn('管理档案 '+icon('arrow'),'go-teams','text-link'))}</div><aside>${card('需要你关注',`<div class="todo-item"><h3><span class="pill amber">训练复盘</span>　现场发生了什么？</h3><p>记录实际人数、调整与可观察行为，供后续备课参考。</p>${btn('去记录反馈 '+icon('arrow'),'go-feedback','text-link')}</div><div class="todo-item"><h3><span class="pill ${state.insight.status==='pending_confirmation'?'amber':'gray'}">${insightLabel()}</span>　球队认识候选</h3><p>基于两次虚构观察提出，确认前不会进入长期上下文。</p>${btn('查看依据 '+icon('arrow'),'insight','text-link')}</div>`)}${card('当前训练周期',`<span class="pill">进行中</span><h3 style="margin-top:17px">${esc(state.cycle.name)}</h3><p style="font-size:12px;color:#859177">${esc(state.cycle.start)} — ${esc(state.cycle.end)}</p><div class="progress-track"><div class="progress-fill"></div></div><div class="cycle-meta"><span>第 1 / 4 周 · 样例</span><span>${state.cycle.minutes}分钟 / 次</span></div><hr class="divider"><small>周期覆盖：${state.cycle.players}人 · ${esc(state.cycle.venue)}</small>`)}</aside></div>`;
}
function teams() { return header('球队与周期','长期背景与阶段安排，各自保留。') + `<div class="notice green">本次明确输入 → 当前生效周期 → 球队长期档案。更具体的临时条件优先，周期内容不会自动改写球队档案。</div><div class="two-col"><div>${card('球队长期档案',`<form id="team-form" class="form-grid"><label class="full">球队名称<input name="name" required maxlength="40" value="${esc(state.team.name)}"></label><label>默认人数<input name="players" type="number" min="4" max="40" required value="${state.team.players}"></label><label>默认时长（分钟）<input name="minutes" type="number" min="20" max="120" required value="${state.team.minutes}"></label><label class="full">默认场地<input name="venue" required maxlength="80" value="${esc(state.team.venue)}"></label><label class="full">长期培养目标<textarea name="goal" required maxlength="300">${esc(state.team.goal)}</textarea></label><div class="full actions">${btn('保存球队档案','submit-team','primary','type="submit"')}<small>仅保存在本浏览器</small></div></form>`)}${card('当前生效周期',`<form id="cycle-form" class="form-grid"><label class="full">周期名称<input name="name" required maxlength="60" value="${esc(state.cycle.name)}"></label><label>开始日期<input name="start" type="date" required value="${state.cycle.start}"></label><label>结束日期<input name="end" type="date" required value="${state.cycle.end}"></label><label>覆盖人数<input name="players" type="number" min="4" max="40" required value="${state.cycle.players}"></label><label>覆盖时长（分钟）<input name="minutes" type="number" min="20" max="120" required value="${state.cycle.minutes}"></label><label class="full">覆盖场地<input name="venue" required maxlength="80" value="${esc(state.cycle.venue)}"></label><label class="full">阶段目标<textarea name="goal" required maxlength="300">${esc(state.cycle.goal)}</textarea></label><div class="full actions">${btn('保存周期设置','submit-cycle','primary','type="submit"')}<span class="pill">单一生效周期演示</span></div></form>`)}</div><aside>${card('上下文如何生效',`<div class="context-row"><span>本次输入</span><strong>备课时明确指定</strong></div><div class="context-row"><span>周期覆盖</span><strong>${state.cycle.players}人 / ${state.cycle.minutes}分钟</strong></div><div class="context-row"><span>球队默认</span><strong>${state.team.players}人 / ${state.team.minutes}分钟</strong></div><p class="aside-tip">示例生成固定使用16人、60分钟；为避免假装理解任意条件，修改档案后仍需在备课页明确载入演示条件。</p>`)}${card('球队概览',`<span class="pill">U12 · 发展阶段样例</span><p style="margin-top:18px;font-size:13px">2名教练共同负责。球队资料归青禾青训机构空间，个人账号与机构空间分离。</p><div class="notice">所有名称与记录均为虚构；不含真实球员个人资料。</div>`)}</aside></div>`; }
function planPanel() {
  if (busy) return `<div class="busy"><span class="eyebrow">预设交互演示 · 不调用模型</span><h2 style="margin-top:15px">${['整理示例需求','选择演示参考','加载预设方案'][stage]}</h2><ol>${['读取16人、60分钟的固定演示条件','展示虚构参考说明，不执行案例检索','完成后自动保存当前内容及历史快照'].map((s,i)=>`<li class="${i===stage?'running':''}">${s}</li>`).join('')}</ol>${btn('取消本次演示','cancel','secondary')}<p class="aside-tip">取消保留原方案，不写入未完成结果。</p></div>`;
  if (!state.current) return `<div class="empty">${icon('spark')}<h2>从一堂具体的训练开始</h2><p>选择左侧的完整课次场景，体验需求整理、预设方案、持续修改与历史版本。</p><span class="pill">预设演示，无真实 AI 请求</span></div>`;
  const p = state.current;
  return `<div class="plan-intro"><div><span class="pill">完整训练课 · 虚构样例</span><h2>${esc(p.title)}</h2><p>${p.players}人 · ${p.minutes}分钟 · ${esc(p.contextSnapshot?.team?.name || '历史球队未记录')}</p><p class="aside-tip">创建时周期：${esc(p.contextSnapshot?.cycle?.name || '历史周期未记录')}</p></div><span class="pill gray">v${state.versions.at(-1)?.id}</span></div>${pitch()}<p class="aside-tip">场地图为组织示意，非精确尺寸。无需守门员；16个球、标志盘、分队背心。</p><div class="notice green">训练目标：${esc(p.goal)}</div><div class="timeline">${p.activities.map(a=>`<div class="activity"><span class="minute">${a.duration}′</span><div><h3>${esc(a.name)}</h3><p>${esc(a.detail)}</p></div></div>`).join('')}</div><div class="status-line">${icon('check')} 时间合计 ${p.activities.reduce((sum,a)=>sum+a.duration,0)} / ${p.minutes} 分钟 · 结构演示检查，不代表专业审核</div><div class="plan-bottom"><label>教练备注 · 仅填写虚构内容，原样导出<textarea id="plan-notes" maxlength="500">${esc(p.notes)}</textarea></label><p class="aside-tip">设计理由：从观察与移动逐步过渡到有方向的比赛。示例练习为虚构演示内容，未引用正式案例库。</p><div class="actions">${btn('改为45分钟','modify','secondary',p.minutes===45?'disabled':'')}${btn('版本历史 '+state.versions.length,'history','secondary')}${btn('导出演示文本','export','primary')}</div></div>`;
}
function design() { return header('训练设计','让上下文进入备课，让每次修改都有来处。',state.current&&!busy?btn('去记录训练反馈 '+icon('arrow'),'go-feedback','secondary'):'') + `<div class="designer"><aside>${card('备课需求',`<div class="tabs" role="group" aria-label="方案类型">${[['single','单项练习'],['full','完整课次'],['multi','长期框架']].map(([id,label])=>`<button data-action="mode" data-mode="${id}" class="${mode===id?'selected':''}" ${busy?'disabled':''}>${label}</button>`).join('')}</div>${mode==='full'?`<div class="stack"><label>演示场景<select id="scenario" ${busy?'disabled':''}><option>U12 · 接应与向前传递</option></select></label><label>训练需求<textarea readonly>16人，60分钟，半片七人制场地。通过传跑与小场比赛，让队员传球后主动移动接应。</textarea></label><div class="notice green">本次明确输入：16人 / 60分钟。此次演示输入优先于周期和档案。</div>${btn(icon('spark')+' 体验示例生成','generate','primary',busy?'disabled':'')}<small>按钮载入预设方案。自由需求输入与实时 AI 生成未接入。</small></div>`:`<div class="notice">${mode==='single'?'单项练习':'长期计划框架'}是产品设计中的独立入口，本 Demo 仅展示结构；完整交互请使用“完整课次”。</div><div class="template">${mode==='single'?'目标 → 组织 → 规则 → 教练提示 → 调整选项':'周期目标 → 每周重点 → 课次建议 → 回顾节点'}</div><div class="form-actions">${btn('体验完整课次','full-mode','secondary')}</div>`}`)}${card('本次上下文',`<div class="context-row"><span>球队</span><strong>${esc(state.team.name)}</strong></div><div class="context-row"><span>当前周期</span><strong>${esc(state.cycle.name)}</strong></div><div class="context-row"><span>周期条件</span><strong>${state.cycle.players}人 / ${state.cycle.minutes}分钟</strong></div><div class="context-row"><span>长期认识</span><strong>${state.insight.status==='confirmed'||state.insight.status==='revised'?'已确认，可作背景':'候选未纳入'}</strong></div>${state.insight.status==='confirmed'||state.insight.status==='revised'?`<p class="aside-tip">${esc(state.insight.statement)}</p>`:''}<p class="aside-tip">记忆优先级：本次输入 → 生效周期 → 球队档案 → 相关已确认认识 → 相关历史 → 教练偏好。</p>`)}</aside><div>${card('训练方案',planPanel(),!busy?btn('能力说明','capabilities','text-link'):'')}</div></div>`; }
function library() { const visible=state.current && (!libraryQuery || `${state.current.title} ${state.current.contextSnapshot?.team?.name || ''}`.toLowerCase().includes(libraryQuery.toLowerCase())) && ['all','full'].includes(libraryType); return header('方案库','当前内容持续保存，历史快照保留每次完成的生成与修改。')+`<div class="toolbar"><input id="library-search" aria-label="搜索方案或球队" placeholder="搜索方案名称、球队…" value="${esc(libraryQuery)}"><select id="library-type" aria-label="筛选方案类型"><option value="all" ${libraryType==='all'?'selected':''}>全部方案类型</option><option value="full" ${libraryType==='full'?'selected':''}>完整训练课</option><option value="single" ${libraryType==='single'?'selected':''}>单项练习</option><option value="multi" ${libraryType==='multi'?'selected':''}>长期框架</option></select></div><div id="library-results">${libraryResults(visible)}</div>`; }
function libraryResults(visible) { return visible?`<div class="plan-list"><article class="card plan-tile"><div class="actions"><span class="pill">完整训练课</span><span class="pill gray">active · 当前</span></div><h2>${esc(state.current.title)}</h2><p>${esc(state.current.contextSnapshot?.team?.name || '历史球队未记录')} · ${state.current.players}人 · ${state.current.minutes}分钟</p><small>${state.versions.length}份完整历史快照 · 仅本浏览器</small><div class="tile-foot">${btn('打开方案 '+icon('arrow'),'go-design','text-link')}${btn('版本差异','history','secondary')}</div></article></div>`:`<section class="card empty">${icon('book')}<h2>${state.current?'没有匹配的方案':'你的第一堂训练，从这里留下来'}</h2><p>${state.current?'试试其他关键词或方案类型。':'完成示例生成后，当前内容与历史版本会自动进入方案库。'}</p>${btn(state.current?'清除筛选':'开始备课',state.current?'clear-filter':'go-design','secondary')}</section>`; }
function insightLabel() { return {pending_confirmation:'待确认',confirmed:'已确认',revised:'已修订并确认',invalidated:'已拒绝'}[state.insight.status]; }
function feedback() { return header('训练反馈','记录现场发生的事，让下一次备课有依据。')+`<div class="two-col"><div>${card('记录一次训练观察',`<p class="muted" style="font-size:12px">演示训练：10月25日 · ${esc(state.current?.title||'向前传递，接应与创造空间')}</p><form id="feedback-form" class="form-grid"><label>实际人数<input name="players" type="number" min="1" max="40" required value="15"></label><label>执行状态<input value="已完成 · 记录现场观察" readonly><input type="hidden" name="status" value="completed"></label><label class="full">现场调整<textarea name="changes" required maxlength="500" placeholder="如：1人未到，调整为两组轮换…"></textarea></label><label class="full">目标行为的可观察证据<textarea name="observations" required maxlength="800" placeholder="如：第二轮有队员传球后主动移动到侧前方接应…"></textarea></label><label>组织可行性<select name="feasibility"><option>可顺利组织</option><option>需要调整</option><option>难以组织</option></select></label><label>复用意愿<select name="reuse"><option>愿意复用</option><option>调整后复用</option><option>暂不复用</option></select></label><div class="full">${btn('保存训练反馈','submit-feedback','primary','type="submit"')}</div></form><p class="aside-tip">此表仅记录已完成训练。计划与取消状态在工作台安排中管理；反馈不自动成为下一次目标或长期结论。</p>`)}${card(`本地反馈历史 · ${state.feedback.length}条`,state.feedback.length?state.feedback.slice().reverse().map((f,i)=>`<article class="version"><div class="version-header"><strong>训练观察 ${state.feedback.length-i}</strong><span class="pill gray">${{completed:'已完成',planned:'计划中',cancelled:'已取消'}[f.status]}</span></div><p>${f.players}人 · ${esc(f.feasibility)} · ${esc(f.reuse)}</p><div class="observations">${esc(f.observations)}</div><p>现场调整：${esc(f.changes)}</p></article>`).join(''):'<p class="muted" style="font-size:12px">尚未提交反馈。上方表单可记录一次虚构训练观察。</p>')}</div><aside>${card('球队长期认识',`<span class="pill ${state.insight.status==='pending_confirmation'?'amber':'gray'}">${insightLabel()}</span><p style="font-size:13px;margin-top:18px">${esc(state.insight.statement)}</p><div class="observations">依据：${state.insight.evidence.map(esc).join('、')}。<br>适用范围：U12蓝队，小场方向比赛。<br>以上为预设样例，未由本次反馈自动归纳。</div><p class="aside-tip">确认前仅是候选；确认或修订确认后，才会进入备课页的长期上下文。</p>${btn('查看与处理','insight','secondary')}`)}${card('观察，而不是标签',`<p style="font-size:12px;color:#7d8c73">用“第二轮开始前主动观察身后”描述具体行为，保留时间和情境。一次表现不能推导永久能力、人格或兴趣。</p>`)}</aside></div>`; }
function organization() { const members=[['林','林教练','球队主教练','U12 蓝队'],['陈','陈教练','技术主管','机构全部球队'],['许','许教练','助理教练','U12 蓝队'],...state.invites.map(n=>[n.slice(0,1),n,'模拟邀请','尚未分配'])]; return header('机构协作','个人账号长期保留，机构资料归机构空间。')+`<div class="notice">角色切换仅预览界面，不提供身份认证、访问控制或真实邀请。当前演示视角：${role==='director'?'技术主管':'球队主教练'}。</div><div class="toolbar"><label style="display:flex;align-items:center;gap:12px">展示视角<select id="role-view"><option value="head" ${role==='head'?'selected':''}>球队主教练</option><option value="director" ${role==='director'?'selected':''}>技术主管</option></select></label>${btn('本地模拟邀请','invite','secondary')}</div><div class="two-col"><div>${card('青禾青训 · 成员与球队分配',members.map(([initial,name,r,team])=>`<div class="member"><div class="avatar">${esc(initial)}</div><div class="member-info"><h3>${esc(name)}</h3><p>${esc(team)}</p></div><span class="pill gray">${esc(r)}</span></div>`).join(''))}${role==='director'?card('机构球队 · 主管视角',`<div class="context-row"><span>U12 蓝队</span><strong>林教练 / 许教练</strong></div><div class="context-row"><span>U10 绿队</span><strong>周教练 · 仅展示</strong></div><p class="aside-tip">主管可查看机构全部球队是产品设计规则。此处仅显示虚构信息，无真实权限实现。</p>`):card('我的球队 · 教练视角',`<div class="context-row"><span>${esc(state.team.name)}</span><strong>球队主教练</strong></div><p class="aside-tip">普通教练仅访问获分配球队是产品设计规则，此处仅作视图演示。</p>`)}</div><aside>${card('机构模板',`<div class="template"><span class="pill">脱敏模板预览</span><h3 style="margin:15px 0 8px">小场方向比赛 · 组织框架</h3><p>目标 → 人数与场地 → 轮换组织 → 观察提示 → 调整选项</p>${btn('查看模板结构','template','text-link')}</div>`)}${card('数据归属',`<p style="font-size:12px;color:#7f8b76">机构球队、方案、反馈与历史属于青禾青训空间。成员离开后，个人账号仍保留，机构资料不会自动复制到个人空间。</p><small>真实成员撤权、跨空间数据转移及模板发布不在本次交互中。</small>`)}</aside></div>`; }
function render() { if (!nav.some(n=>n[0]===page)) page='home'; const title=nav.find(n=>n[0]===page)[1]; document.title=`${title} · 蹴鞠`; $('#app').innerHTML=`<div class="layout"><div class="mobile-scrim ${mobileOpen?'open':''}" data-action="close-nav"></div><aside id="main-sidebar" class="sidebar ${mobileOpen?'open':''}" aria-label="主导航"><a class="brand" href="#home">${icon('ball')}蹴鞠</a><div class="brand-sub">COACH WORKSPACE</div><div class="space-card"><span class="space-avatar">青</span><div>青禾青训<small style="display:block;color:#95ae9e">机构空间 · 虚构样例</small></div></div><div class="nav-label">工作空间</div><nav class="nav">${nav.map(([id,label,i])=>`<a href="#${id}" ${page===id?'aria-current="page"':''} class="${page===id?'active':''}">${icon(i)}${label}</a>`).join('')}</nav><div class="sidebar-bottom"><button class="capability" data-action="capabilities">${icon('spark')}　关于这个演示　↗</button><div class="profile"><span class="avatar">林</span><div style="font-size:12px">林教练<small style="display:block;color:#8ca998">个人账号 · 机构成员</small></div></div></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb"><button class="mobile-toggle" aria-label="打开导航" aria-expanded="${mobileOpen}" aria-controls="main-sidebar" data-action="menu">${icon('menu')}</button><span class="desktop">青禾青训</span><span class="desktop">/</span><span>${title}</span></div><div class="top-right"><span class="saved">${storageAvailable?'已保存本浏览器':'当前仅保留在页面中'}</span><span class="demo-tag">交互演示 · 样例数据</span><button aria-label="查看演示能力说明" data-action="capabilities" class="avatar">?</button></div></header><main class="content" id="main" tabindex="-1">${({home,teams,design,library,feedback,organization})[page]()}<div class="footer-note">蹴鞠 · 教练团队训练规划产品探索　/　虚构脱敏样例 · Agent 为预设演示</div></main></div></div>`; syncNavigationAccessibility(); }
function openDialog(title, html) { $('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close-dialog" aria-label="关闭弹层">×</button></div><div class="dialog-body">${html}</div>`; $('#dialog').showModal(); }
function capabilities() { openDialog('关于这个演示',`<span class="pill">作品展示 · 非生产服务</span><h3>现在可以体验</h3><p>六页导航、虚构档案编辑、预设方案生成与取消、45分钟示例修改、历史恢复、文本导出、反馈记录及长期认识确认。改动仅保存在当前浏览器。</p><h3>产品设计展示</h3><p>个人账号与机构空间分离、球队与训练周期、组织角色视角、反馈与长期记忆分层。角色切换仅作展示；真实权限、机构邀请、审批、定价均未实现。</p><h3>独立 Agent 研发边界</h3><p>项目另有独立 Agent 研发与验证记录。本 Demo 不连接其后端、模型、数据库或真实案例检索，不展示真实模型运行结果。示例训练内容未经专业审核。</p><h3>本地数据</h3><p>使用独立的浏览器存储。重置仅清除此 Demo 的虚构记录，随后恢复初始场景。</p>${btn('重置本地演示数据','reset-confirm','danger')}`); }
function history() { if (!state.current) return toast('先体验一次示例生成。'); openDialog('完整版本历史',`<p class="muted">恢复会创建新版本；原快照始终保留。当前备注自动保存，连续编辑不会逐键生成快照。</p>${state.versions.slice().reverse().map(v=>`<article class="version"><div class="version-header"><strong>v${v.id} · ${esc(v.summary)}</strong>${btn('恢复为新版本','restore','secondary',`data-id="${v.id}"`)}</div><p>${new Date(v.createdAt).toLocaleString('zh-CN')} · ${v.content.minutes}分钟${v.baseId?` · 基于v${v.baseId}`:''}</p><p>背景快照：${esc(v.content.contextSnapshot?.team?.name || '历史球队未记录')} · ${esc(v.content.contextSnapshot?.cycle?.name || '历史周期未记录')}</p><div class="diff"><div><small>此快照</small><p>${v.content.activities.map(a=>`${esc(a.name)} ${a.duration}′`).join('<br>')}</p></div><div><small>当前内容</small><p>${state.current.activities.map(a=>`${esc(a.name)} ${a.duration}′`).join('<br>')}</p></div></div><p>快照备注：${esc(v.content.notes)}</p></article>`).join('')}`); }
function insight() { openDialog('确认球队长期认识',`<span class="pill ${state.insight.status==='pending_confirmation'?'amber':'gray'}">${insightLabel()}</span><p style="margin-top:18px">依据：${state.insight.evidence.map(esc).join('、')}。均为预设虚构训练观察，不含真实评估结果。</p><form id="insight-form"><label>候选认识 · 可修改后确认<textarea name="statement" required maxlength="500">${esc(state.insight.statement)}</textarea></label><p class="aside-tip">适用范围：U12 蓝队、小场方向比赛。确认只影响本 Demo 备课上下文，不修改球队长期目标。</p><div class="actions">${btn('确认作为长期认识','submit-insight','primary','type="submit"')}${btn('拒绝此候选','reject-insight','secondary')}</div></form>`); }
async function generate(minutes=60) { if (busy) return; busy=true; stage=0; const token=++job; render(); for(let i=0;i<3;i++) { stage=i; if(page==='design') render(); await new Promise(resolve=>setTimeout(resolve,850)); if(token!==job) return; } saveVersion(state,preset(minutes),minutes===45?'调整为45分钟示例':'载入60分钟示例'); busy=false; persist(); render(); toast('预设方案已完成，当前内容与完整快照已保存。'); }
function cancel() { job++; busy=false; render(); toast('演示已取消，原方案和历史保持。'); }
function go(target) { location.hash=target; }
function exportCurrent() { if (!state.current) return; const blob=new Blob([exportPlan(state)],{type:'text/plain;charset=utf-8'}); const url=URL.createObjectURL(blob); const link=document.createElement('a'); link.href=url; link.download='蹴鞠_虚构训练方案.txt'; link.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); toast('已交付演示文本下载；自由备注会原样导出，请仅填写虚构内容。'); }
document.addEventListener('click', event => { const node=event.target.closest('[data-action]'); if(!node) return; const action=node.dataset.action; if(action.startsWith('submit-'))return; if(action.startsWith('go-')) {go(action.slice(3));return;} if(action==='menu'){mobileOpen=true;render();$('.nav a').focus();return;} if(action==='close-nav'){mobileOpen=false;render();$('.mobile-toggle').focus();return;} if(action==='close-dialog'){ $('#dialog').close();return;} if(action==='capabilities')return capabilities(); if(action==='mode'){mode=node.dataset.mode;render();return;} if(action==='full-mode'){mode='full';render();return;} if(action==='generate')return generate(); if(action==='modify')return generate(45); if(action==='cancel')return cancel(); if(action==='history')return history(); if(action==='restore'){if(busy)return toast('请先取消或等待本次演示完成。');restoreVersion(state,Number(node.dataset.id));persist();$('#dialog').close();render();toast('已恢复为新版本，原历史快照保留。');return;} if(action==='export')return exportCurrent(); if(action==='insight')return insight(); if(action==='reject-insight'){state.insight.status='invalidated';persist();$('#dialog').close();render();toast('已拒绝，不作为长期上下文。');return;} if(action==='clear-filter'){libraryQuery='';libraryType='all';render();return;} if(action==='reset-confirm'){openDialog('重置演示数据',`<p>将清除此 Demo 在本浏览器保存的方案、版本、反馈、档案修改及模拟邀请，恢复初始虚构场景。</p><div class="actions">${btn('确认重置','reset','danger')}${btn('保留数据','close-dialog','secondary')}</div>`);return;} if(action==='reset'){job++;busy=false;state=initialState();persist();$('#dialog').close();render();toast('本 Demo 已重置。');return;} if(action==='invite'){openDialog('本地模拟邀请',`<p class="muted">仅向本地虚构成员列表添加记录，不发送邮件或消息。</p><form id="invite-form" class="stack"><label>演示成员称呼<input name="name" required maxlength="30" placeholder="例如：周教练"></label>${btn('添加模拟邀请','submit-invite','primary','type="submit"')}</form>`);return;} if(action==='template'){openDialog('机构模板 · 结构预览',`<span class="pill">脱敏通用框架</span><h3>小场方向比赛</h3><p>明确本次目标 → 确认人数和可用场地 → 按人数设计分组轮换 → 规定得分方向 → 设置观察提示 → 课后记录可见行为。</p><p class="muted">这是机构模板产品结构演示，未创建正式案例，未执行模板审批或发布。</p>`);return;} if(action==='event'){openDialog('本次训练安排',`<p>10月25日 · 16:00 · ${esc(state.team.name)}<br>执行状态独立于方案保存，状态不会表示专业审核或采用审批。</p><form id="event-form" class="stack"><label>执行状态<select name="status">${[['planned','计划中'],['completed','已完成'],['cancelled','已取消']].map(([v,l])=>`<option value="${v}" ${state.eventStatus===v?'selected':''}>${l}</option>`).join('')}</select></label>${btn('保存执行状态','submit-event','primary','type="submit"')}</form>`);return;} if(action==='schedule')openDialog('训练安排 · 预览',`<p>10月24日，17:00–18:00<br>U12蓝队 · 控球后寻找向前线路</p><p class="muted">此项是未来训练安排的虚构预览。当前可交互的备课场景为10月25日完整课次。</p>${btn('进入可体验的备课场景','go-design','primary')}`); });
document.addEventListener('submit', event => { const form=event.target; if(!form.id.endsWith('-form'))return; event.preventDefault();const data=Object.fromEntries([...new FormData(form)].map(([key,value])=>[key,typeof value==='string'?value.trim():value])); if([...form.querySelectorAll('[required]')].some(input=>!String(data[input.name]??'').trim()))return toast('请填写有效内容，不能仅输入空格。'); if(form.id==='team-form'||form.id==='cycle-form'){if(busy)return toast('请先取消或等待生成完成。');data.players=Number(data.players);data.minutes=Number(data.minutes);if(form.id==='cycle-form'&&data.end<data.start)return toast('结束日期需要晚于或等于开始日期。');state[form.id==='team-form'?'team':'cycle']=data;persist();render();toast('档案已保存本浏览器。');} if(form.id==='feedback-form'){state.feedback.push({...data,status:'completed',players:Number(data.players),createdAt:new Date().toISOString()});state.eventStatus='completed';persist();render();toast('训练反馈已保存，长期认识没有自动改变。');} if(form.id==='insight-form'){state.insight.status=data.statement===state.insight.statement?'confirmed':'revised';state.insight.statement=data.statement;persist();$('#dialog').close();render();toast('长期认识已明确确认，可在演示备课上下文中查看。');} if(form.id==='invite-form'){state.invites.push(data.name);persist();$('#dialog').close();render();toast('已添加本地模拟邀请，未发送任何消息。');} if(form.id==='event-form'){state.eventStatus=data.status;persist();$('#dialog').close();render();toast('执行状态已保存。');} });
document.addEventListener('input', event => {if(event.target.id==='plan-notes'&&!busy&&state.current){state.current.notes=event.target.value;persist();}if(event.target.id==='library-search'){libraryQuery=event.target.value;$('#library-results').innerHTML=libraryResults(state.current&&(!libraryQuery||`${state.current.title} ${state.current.contextSnapshot?.team?.name || ''}`.toLowerCase().includes(libraryQuery.toLowerCase()))&&['all','full'].includes(libraryType));}});
document.addEventListener('change',event=>{if(event.target.id==='library-type'){libraryType=event.target.value;render();}if(event.target.id==='role-view'){role=event.target.value;render();}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';mobileOpen=false;if($('#dialog').open)$('#dialog').close();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mobileOpen){mobileOpen=false;render();$('.mobile-toggle').focus();}});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const box=$('#dialog').getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)$('#dialog').close();}});
render();

$('.skip').addEventListener('click', event => { event.preventDefault(); $('#main').focus(); $('#main').scrollIntoView(); });
function syncNavigationAccessibility() {
  const sidebar = $('#main-sidebar');
  if (!sidebar) return;
  const hidden = window.matchMedia('(max-width:650px)').matches && !mobileOpen;
  sidebar.inert = hidden;
  if (hidden) sidebar.setAttribute('aria-hidden', 'true');
  else sidebar.removeAttribute('aria-hidden');
}
window.matchMedia('(max-width:650px)').addEventListener('change', syncNavigationAccessibility);
syncNavigationAccessibility();